import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';

/**
 * Autogenerated rather than hand-listed on purpose: with `path: '../docs'` and
 * `routeBasePath: '/'`, hand-written doc IDs are fragile — adding a page to
 * `docs/` must not require editing this file, and a renamed page must not break
 * the build with an ID that no longer exists.
 */
const sidebars: SidebarsConfig = {
  docs: [{ type: 'autogenerated', dirName: '.' }],
};

export default sidebars;
